import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/about.md","filePath":"user-guide/settings/about.md","lastUpdated":1786082398000}'),s={name:"user-guide/settings/about.md"};function n(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>Shows version numbers for the App, Core, Service, and CLI components (colored to reflect whether the service is currently healthy), a short description of Lertaro, and links to the project homepage and the online user guide.</p><h2 id="data-folders" tabindex="-1">Data folders <a class="header-anchor" href="#data-folders" aria-label="Permalink to &quot;Data folders&quot;">​</a></h2><p>Two more links, right below those, open the folders Lertaro reads and writes its own configuration from — each shows the actual path as the clickable link text, creating the folder first if it doesn&#39;t exist yet:</p><ul><li><strong>User Data Folder</strong> — the per-user folder holding <code>user-settings.json</code>. Every time settings are saved, the previous file is rotated into <code>user-settings.json.bak.1</code> (shifting any older backups down, up to <code>.bak.5</code>) before the new one is written, so a bad edit or a crash mid-save always leaves a recent copy to restore from.</li><li><strong>Machine Data Folder</strong> — the shared, machine-wide folder used by the background service (<code>machine-settings.json</code>, index caches, and service-side logs).</li></ul><p>The installed build uses <code>%LocalAppData%\\Lertaro</code> and <code>%ProgramData%\\Lertaro</code>. A portable build uses <code>Data\\Users\\&lt;SID hash&gt;</code> and <code>Data\\Machine</code> beside the application; if that portable <code>Data</code> folder has not been created yet, existing installed data is reused for compatibility. See <a href="./../getting-started.html#portable-data">Portable data</a> for the precedence rule.</p><h2 id="checking-for-updates" tabindex="-1">Checking for updates <a class="header-anchor" href="#checking-for-updates" aria-label="Permalink to &quot;Checking for updates&quot;">​</a></h2><ul><li><strong>Check Update</strong> button — queries for a newer release; the button&#39;s own label reflects progress (&quot;Checking...&quot;, then either &quot;up to date&quot; or the new version number found).</li><li>If a non-administrator account can&#39;t stop the background service to install an update in place, a warning banner explains this and points you to the manual download page instead.</li><li>Once a new version is found: <ul><li><strong>Silent Auto-Update</strong> — downloads and installs in the background, showing a progress bar, then restarts Lertaro automatically.</li><li><strong>Go to Download Page</strong> — opens the GitHub release page in your browser for a manual install.</li></ul></li></ul><p>This mirrors the <strong>Auto check for updates</strong> / <strong>Auto silent update</strong> checkboxes under <a href="./general.html#system">General → System</a> — those control whether this check happens automatically on startup; this page lets you trigger it manually at any time.</p>',9)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
